import{_ as t,o as e,c as a,a5 as o}from"./chunks/framework.CXroN2RO.js";const c="/study/images/network/quic-and-http3.svg",p=JSON.parse('{"title":"QUICとHTTP/3","description":"","frontmatter":{"title":"QUICとHTTP/3","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"UDP上のQUICがTLS 1.3、損失検出、ストリームをどう組み合わせるか。HTTP/2とHTTP/3で欠落がどこまで影響するか、経路の切り替えやDATAGRAM、0-RTTまでたどる。","aliases":["QUIC","HTTP/3","HTTP/2","Head-of-Line Blocking","HOL","ストリーム","コネクションID","QPACK","QUIC DATAGRAM","0-RTT"],"verification":"IETF RFC 9000・9001・9002・9114・9221・9204・8470に照合（2026-11-07）"}},"headers":[],"relativePath":"network/quic-and-http3.md","filePath":"network/quic-and-http3.md"}'),n={name:"network/quic-and-http3.md"};function d(h,r,f,l,i,s){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="quicとhttp-3" tabindex="-1">QUICとHTTP/3 <a class="header-anchor" href="#quicとhttp-3" aria-label="Permalink to &quot;QUICとHTTP/3&quot;">​</a></h1><p>ページの画像AとスタイルシートBを同じ接続で受け取るとき、途中で画像Aのデータが欠けると、先に届いたBは使えるでしょうか。HTTP/2とHTTP/3では、受信側が順番をそろえる単位が違います。<a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-1.1" target="_blank" rel="noreferrer">RFC 9114のHTTP/2との比較</a></p><h2 id="udpの中でquicが担当すること" tabindex="-1">UDPの中でQUICが担当すること <a class="header-anchor" href="#udpの中でquicが担当すること" aria-label="Permalink to &quot;UDPの中でQUICが担当すること&quot;">​</a></h2><p>QUICはUDPデータグラムのペイロードにQUICパケットを載せるトランスポートです。一つのUDPデータグラムに複数のQUICパケットをまとめることがあり、QUICパケットには <code>STREAM</code>、<code>ACK</code>、<code>CRYPTO</code> などのフレームが入ります。QUICは送受信の両端で接続状態を保持し、損失の検出、必要なデータの再送、フロー制御、輻輳制御を行います。例えばネットワークで並び順が変わっても、受信側のQUICがストリームごとにバイト列を組み立てます。<a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-1" target="_blank" rel="noreferrer">RFC 9000の概要</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-12.2" target="_blank" rel="noreferrer">パケットをまとめる仕組み</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-12.4" target="_blank" rel="noreferrer">フレーム</a> · <a href="/study/network/udp-datagrams.html">UDPデータグラム</a></p><p>QUICは接続時に<strong>TLS 1.3のハンドシェイク</strong>を使って相手を認証し、パケット保護用の鍵を導きます。TLSのハンドシェイクデータはQUICの <code>CRYPTO</code> フレームに入ります。HTTPSでTCPを使う場合は、TCPのバイト列にTLSレコードを流します。QUICではレコード層の役割をQUICのパケット保護が担い、アプリデータは <code>STREAM</code> などのQUICフレームに載ります。<a href="https://www.rfc-editor.org/rfc/rfc9001.html#section-3" target="_blank" rel="noreferrer">RFC 9001の構成とTLSメッセージの運搬</a> · <a href="/study/network/tls-https.html">TLSとHTTPS</a></p><h2 id="パケット番号とストリーム内のオフセット" tabindex="-1">パケット番号とストリーム内のオフセット <a class="header-anchor" href="#パケット番号とストリーム内のオフセット" aria-label="Permalink to &quot;パケット番号とストリーム内のオフセット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>値</th><th>何を識別するか</th><th>QUICがどう使うか</th></tr></thead><tbody><tr><td>パケット番号</td><td>ある送信方向・番号空間で送られた一つのQUICパケット</td><td>受信側は <code>ACK</code> で受け取った番号の範囲を返す。送信側は番号と送信時刻を使って損失を検出する。</td></tr><tr><td>ストリームIDとオフセット</td><td>どのストリームの、各方向のバイト列のどの位置か</td><td><code>STREAM</code> フレームを受信側で配置し、先頭から途切れずにそろったバイトを順にアプリに渡す。</td></tr></tbody></table><p>パケット100に <code>Aのオフセット0から4バイト</code> を入れたとします。パケット100の損失を検出し、そのデータがまだ必要なら、送信側は別のパケット番号で同じオフセットのデータを送ります。受信側から見ると、パケットは別物で、埋まるのは同じバイト位置です。パケット番号は、送信方向ごとに <code>Initial</code>、<code>Handshake</code>、<code>Application Data</code> の三つの番号空間に分かれます。0-RTTと1-RTTは <code>Application Data</code> の番号空間を共有します。<a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-2.2" target="_blank" rel="noreferrer">RFC 9000のストリームの送受信</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-12.3" target="_blank" rel="noreferrer">パケット番号の空間</a> · <a href="https://www.rfc-editor.org/rfc/rfc9002.html#section-3" target="_blank" rel="noreferrer">RFC 9002の送信と損失検出</a></p><p>ストリームがアプリに渡すのは順序付きのバイト列です。例えば、送り手が4バイトずつ2回書き込んでも、受け手が8バイトを一度に読む場合があります。ゲームのメッセージなどを区別するには、長さを先頭に置くなど、アプリ側で区切りを定めます。<a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-2.2" target="_blank" rel="noreferrer">RFC 9000のストリームの送受信</a></p><h2 id="http-2とhttp-3で、損失の影響をたどる" tabindex="-1">HTTP/2とHTTP/3で、損失の影響をたどる <a class="header-anchor" href="#http-2とhttp-3で、損失の影響をたどる" aria-label="Permalink to &quot;HTTP/2とHTTP/3で、損失の影響をたどる&quot;">​</a></h2><p><strong>HTTP/2</strong>は複数のHTTPストリームを一つのTCP接続に多重化します。図のようにAの部分を運ぶTCPセグメントが欠けると、TCPのバイト列に穴ができます。Bのバイトが受信側に届いていても、穴より後ろにあれば、TCPから上の層へ渡せるようになるまで待ちます。先にある欠落が後続のデータを足止めする現象を <strong>Head-of-Line Blocking（HOLブロッキング）</strong> と呼びます。<a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-1.1" target="_blank" rel="noreferrer">RFC 9114のHTTP/2との比較</a> · <a href="/study/network/tcp-sockets.html">ソケットとTCP通信</a></p><p><strong>HTTP/3</strong>は、クライアントからの各リクエストと対応するレスポンスに一つずつ双方向のQUICストリームを使います。設定などを伝える制御用ストリームは別にあります。Aのオフセット0が欠けていても、Bのバイトが先頭からそろっていれば、受信側のQUICはBを先にHTTP/3へ渡せます。Aの後続部分は、Aの中で欠けた範囲が届くまで待ちます。<a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-6" target="_blank" rel="noreferrer">RFC 9114のストリームへの対応付け</a></p><figure class="study-figure"><img src="'+c+'" alt="Aの先頭だけが欠けた例。HTTP/2では後から届いたBも同じTCPバイト列の穴を待つ。HTTP/3では別ストリームのBを先に渡せる。Aの先頭を新しいQUICパケットで受け取ると、Aの後続も順に渡せる。" width="760" height="478" loading="lazy"><figcaption>Aの先頭、Bの先頭、Aの後続を、それぞれ別のTCPセグメントまたはQUICパケットで送った例です。<a href="/study/images/network/quic-and-http3.svg" target="_blank" rel="noopener noreferrer">損失の影響を比べる図を拡大</a></figcaption></figure><p>QUICでも、次のような条件では複数のストリームに影響が及びます。</p><ul><li><strong>同じパケットに入っていたデータ。</strong> 一つのQUICパケットにAとBの <code>STREAM</code> フレームが入っていれば、そのパケットを失うと両方のバイト列に穴ができます。<a href="https://www.rfc-editor.org/rfc/rfc9002.html#section-3" target="_blank" rel="noreferrer">RFC 9002のパケットとフレーム</a></li><li><strong>接続が共有する送信の余力。</strong> 同じ経路を使うストリームは輻輳ウィンドウを共有します。損失に反応して送信できる量が減ると、Bの次の送信も遅くなり得ます。また、受信側が示す接続全体のフロー制御上限 <code>MAX_DATA</code> に達すると、上限が増えるまで新しいストリームデータを送れません。<a href="https://www.rfc-editor.org/rfc/rfc9002.html#section-7" target="_blank" rel="noreferrer">RFC 9002の輻輳制御</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-4.1" target="_blank" rel="noreferrer">RFC 9000のフロー制御</a> · <a href="/study/network/latency-throughput-and-queues.html">遅延・帯域・待ち行列</a></li><li><strong>HTTP/3のヘッダー圧縮。</strong> QPACKで動的テーブルを参照するヘッダーは、必要なテーブル更新が別ストリームから届くまでデコードを待つことがあります。データを運ぶ層でBが読めても、その上のHTTP処理で待つ場合です。<a href="https://www.rfc-editor.org/rfc/rfc9204.html#section-2.1.2" target="_blank" rel="noreferrer">RFC 9204のブロックされるストリーム</a></li></ul><p><a href="/study/practice/network/stream-loss-observation.html">パケット損失とストリームの実践</a>では、欠けるパケットを変えながら、AとBを受信側のアプリへ渡せる段階を図で追えます。</p><h2 id="ストリームとquic-datagramの使い分け" tabindex="-1">ストリームとQUIC DATAGRAMの使い分け <a class="header-anchor" href="#ストリームとquic-datagramの使い分け" aria-label="Permalink to &quot;ストリームとQUIC DATAGRAMの使い分け&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途の例</th><th>QUICで運ぶ単位</th><th>損失時の扱い</th></tr></thead><tbody><tr><td>確定した結果、ファイル</td><td>ストリームのバイト列</td><td>欠けた部分を再送して、同じストリーム内で順序どおりに渡す。</td></tr><tr><td>最新の位置や向きで上書きできるスナップショット</td><td><code>DATAGRAM</code> フレームに収まる一つのメッセージ</td><td>QUICによる再送や順序保証はない。更新番号などを見て、受信側で古いものを捨てられる。</td></tr></tbody></table><p><strong>QUIC DATAGRAM</strong>は拡張機能です。送るには相手が <code>max_datagram_frame_size</code> で受信対応を示している必要があります。アプリデータの暗号化と経路の輻輳制御はストリームと同じQUIC接続で行われるため、混雑時はDATAGRAMも送信を待つか、捨てられます。DATAGRAMを含むパケットに <code>ACK</code> が返っても、相手のアプリで結果が適用されたかは、アプリ側の応答で確認します。<a href="https://www.rfc-editor.org/rfc/rfc9221.html#section-3" target="_blank" rel="noreferrer">RFC 9221のトランスポートパラメータ</a> · <a href="https://www.rfc-editor.org/rfc/rfc9221.html#section-5" target="_blank" rel="noreferrer">受信とACK・輻輳制御</a></p><h2 id="ipアドレスやポートが変わったとき" tabindex="-1">IPアドレスやポートが変わったとき <a class="header-anchor" href="#ipアドレスやポートが変わったとき" aria-label="Permalink to &quot;IPアドレスやポートが変わったとき&quot;">​</a></h2><p>Wi-Fiからモバイル回線へ切り替えると、送信元IPアドレスやUDPポートが変わることがあります。NATが外側のポートを割り当て直した場合も、相手からは送信元が変わって見えます。QUICでは端点が<strong>コネクションID</strong>を手がかりに受信パケットを既存の接続に対応付けます。一つの接続に複数のIDを用意できるので、経路を変えるときは別のIDで同じ接続を指せます。新しい経路の検証では、<code>PATH_CHALLENGE</code> で送った値を相手が <code>PATH_RESPONSE</code> で返せるかを確認します。QUIC v1でハンドシェイク確認後に能動的な移行を始めるのはクライアントで、サーバーは能動的な移行を無効にする設定を通知できます。<a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-5.1" target="_blank" rel="noreferrer">RFC 9000のコネクションID</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-8.2" target="_blank" rel="noreferrer">経路の検証</a> · <a href="https://www.rfc-editor.org/rfc/rfc9000.html#section-9" target="_blank" rel="noreferrer">接続の移行</a> · <a href="/study/network/nat-and-port-mapping.html">NATとポートの対応付け</a></p><h2 id="_0-rttで先に送るデータを選ぶ" tabindex="-1">0-RTTで先に送るデータを選ぶ <a class="header-anchor" href="#_0-rttで先に送るデータを選ぶ" aria-label="Permalink to &quot;0-RTTで先に送るデータを選ぶ&quot;">​</a></h2><p><strong>0-RTT（Early Data）<strong>では、以前の接続で得た再開用の情報を使い、クライアントが新しいハンドシェイクの返事を待つ前にアプリデータを送れます。サーバーはこのデータを拒否できます。また、攻撃者が記録したEarly Dataを再送する</strong>リプレイ</strong>を考慮します。例えば、通貨を消費してアイテムを買う操作は、同じリクエストが再度処理されると困るため、1-RTTのデータとして送ります。HTTPの <code>425 Too Early</code> は、再実行の危険があるリクエストの処理を拒むための応答です。再試行はEarly Dataを使わずに行います。<a href="https://www.rfc-editor.org/rfc/rfc9001.html#section-4.6" target="_blank" rel="noreferrer">RFC 9001の0-RTT</a> · <a href="https://www.rfc-editor.org/rfc/rfc9114.html#section-10.9" target="_blank" rel="noreferrer">RFC 9114のEarly Data</a> · <a href="https://www.rfc-editor.org/rfc/rfc8470.html#section-5.2" target="_blank" rel="noreferrer">RFC 8470の425</a></p>',23)])])}const g=t(n,[["render",d]]);export{p as __pageData,g as default};
